  position: relative;
  overflow: hidden;
  background: transparent;
}

.locked-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.1);
  filter: blur(6px);
  z-index: 1;
}

.locked-card > * {
  position: relative;
  z-index: 2;
}

.locker-icon {
  position: absolute;
  top: 10px;
  right: 10px;
  font-size: 1.5em;
}
