---

**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: the cost to connect two nodes (houses) is the sum of their prices, and some edges (roads) already exist for free. The goal is to add the minimal set of new roads so that the city is fully connected, and the total cost is minimized.

**Approach:**

1. **Find Connected Components:** Use Disjoint Set Union (DSU) to find all connected components after adding the existing roads.
2. **Find the Cheapest House in Each Component:** For each component, find the house with the lowest price.
3. **Connect Components:** To minimize the cost, connect all components to the component containing the globally cheapest house. For each other component, connect its cheapest house to the globally cheapest house.
4. **Output:** Print the number of new roads and the list of roads to be built.

**C++ Implementation:**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n+1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n+1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    // Find cheapest house in each component
    unordered_map<int, pair<long long, int>> comp_min;
    for (int i = 1; i <= n; ++i) {
        int root = dsu.find(i);
        if (comp_min.find(root) == comp_min.end() || a[i] < comp_min[root].first)
            comp_min[root] = {a[i], i};
    }

    // Find the globally cheapest house
    int global_min_house = -1;
    long long global_min_price = LLONG_MAX;
    for (auto& [root, p] : comp_min) {
        if (p.first < global_min_price) {
            global_min_price = p.first;
            global_min_house = p.second;
        }
    }

    // Connect all other components to the global min house
    vector<pair<int, int>> new_roads;
    for (auto& [root, p] : comp_min) {
        if (p.second != global_min_house)
            new_roads.emplace_back(global_min_house, p.second);
    }

    cout << new_roads.size() << "\n";
    for (auto& [u, v] : new_roads)
        cout << u << " " << v << "\n";
    return 0;
}
```

**Explanation:**
- We use DSU to find components.
- For each component, we find its cheapest house.
- We connect all components to the one with the globally cheapest house, minimizing the total cost.

