Here’s a concise and flexible implementation:

```typescript
// 1. Define the Result type
export type Result<T, E = unknown> =
  | { success: true; value: T }
  | { success: false; error: E };

// 2. Synchronous wrapper for any function signature
export function wrap<T extends (...args: any[]) => any, E = unknown>(
  fn: T
): (...args: Parameters<T>) => Result<ReturnType<T>, E> {
  return (...args: Parameters<T>): Result<ReturnType<T>, E> => {
    try {
      const value = fn(...args);
      return { success: true, value };
    } catch (error) {
      return { success: false, error: error as E };
    }
  };
}

// 3. (Optional) Async version for Promise-returning functions
export function wrapAsync<T extends (...args: any[]) => Promise<any>, E = unknown>(
  fn: T
): (...args: Parameters<T>) => Promise<Result<Awaited<ReturnType<T>>, E>> {
  return async (...args: Parameters<T>): Promise<Result<Awaited<ReturnType<T>>, E>> => {
    try {
      const value = await fn(...args);
      return { success: true, value };
    } catch (error) {
      return { success: false, error: error as E };
    }
  };
}

// Example usage:
const safeDivide = wrap((a: number, b: number) => {
  if (b === 0) throw new Error("Division by zero");
  return a / b;
});

