  ports: [{
    containerPort: 8123
    name: "ha-web"
  }]
  volumeMounts: [{
    name:      "ha-config"
    mountPath: "/config"
  }]
}

// nginx container
nginx: #Container & {
  name:  "nginx"
  image: "nginx:latest"
  ports: [{
    containerPort: 80
    name: "nginx-web"
  }]
  volumeMounts: [{
    name:      "nginx-config"
    mountPath: "/etc/nginx/conf.d"
  }]
}

