#include <Wire.h>
#include <RTClib.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define OLED_ADDR 0x3C
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);
RTC_DS3231 rtc;

const int livingRoomTVPin = 2;
const int bedroomTVPin = 3;
const int nightModePin = 4; // Button

unsigned long simStartMillis;
unsigned long simStartTime = 6 * 3600; // Start at 06:00:00
unsigned long SIM_FACTOR = 6; // Default 6:1

void setup() {
  pinMode(livingRoomTVPin, OUTPUT);
  pinMode(bedroomTVPin, OUTPUT);
  pinMode(nightModePin, INPUT_PULLUP);
  Wire.begin();
  rtc.begin();
  display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR);
  display.clearDisplay();
  simStartMillis = millis();
}

void loop() {
  unsigned long realElapsed = (millis() - simStartMillis) / 1000;
  unsigned long simElapsed = realElapsed * SIM_FACTOR;
  unsigned long simTime = (simStartTime + simElapsed) % 86400;
  int hour = simTime / 3600;
  int min = (simTime % 3600) / 60;
  int sec = simTime % 60;

  bool nightMode = digitalRead(nightModePin) == HIGH;
  unsigned long nightDuration = nightMode ? 2 * 3600 : 1 * 3600;

  // Event logic
  bool livingRoomTV = (simTime >= 19*3600 && simTime < 20*3600);
  bool bedroomTVMorning = (simTime >= 6*3600 && simTime < 7*3600);
  bool bedroomTVNight = (simTime >= 22*3600 && simTime < 22*3600 + nightDuration);

  // Flicker simulation
  if (livingRoomTV) analogWrite(livingRoomTVPin, random(80, 255));
  else digitalWrite(livingRoomTVPin, LOW);

  if (bedroomTVMorning || bedroomTVNight) analogWrite(bedroomTVPin, random(80, 255));
  else digitalWrite(bedroomTVPin, LOW);

  // OLED update
  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(0,0);
  display.printf("%02d:%02d:%02d\n", hour, min, sec);
  display.setTextSize(1);
  display.setCursor(0, 30);
  if (bedroomTVMorning) display.print("Morning News");
  else if (livingRoomTV) display.print("Evening TV");
  else if (bedroomTVNight) display.print("Bedtime TV");
  else display.print("Idle");
  display.display();

  delay(100);
}
