To create an infinite scrolling table component in Vue 3 using Pinia and JavaScript, where rows are fetched from a REST API with `start` and `count` parameters, and the table header remains fixed, you can follow these steps:

**1. Pinia Store (e.g., `stores/rows.js`):**

```js
import { defineStore } from 'pinia';

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
  }),
  actions: {
    async fetchRows(start, count) {
      if (this.loading || !this.hasMore) return;
      this.loading = true;
      try {
        const res = await fetch(`/api/rows?start=${start}&count=${count}`);
        const data = await res.json();
        if (data.rows.length < count) this.hasMore = false;
        this.rows.push(...data.rows);
      } catch (e) {
        console.error(e);
      } finally {
        this.loading = false;
      }
    },
    reset() {
      this.rows = [];
      this.hasMore = true;
      this.loading = false;
    }
  }
});
```

**2. Infinite Scrolling Table Component (e.g., `components/InfiniteScrollTable.vue`):**

```vue
<template>
  <div class="table-container" ref="container" @scroll="onScroll">
    <table>
      <thead>
        <tr>
          <th>Col 1</th>
          <th>Col 2</th>
          <th>Col 3</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="row in rowsStore.rows" :key="row.id">
          <td>{{ row.col1 }}</td>
          <td>{{ row.col2 }}</td>
          <td>{{ row.col3 }}</td>
        </tr>
        <tr v-if="rowsStore.loading">
          <td colspan="3">Loading...</td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRowsStore } from '../stores/rows';

const rowsStore = useRowsStore();
const container = ref(null);
const BATCH_SIZE = 20;

const loadMore = () => {
  rowsStore.fetchRows(rowsStore.rows.length, BATCH_SIZE);
};

const onScroll = () => {
  const el = container.value;
  if (!el) return;
  if (el.scrollTop + el.clientHeight >= el.scrollHeight - 100) {
    loadMore();
  }
};

onMounted(() => {
  rowsStore.reset();
  loadMore();
});
</script>

