#include <iostream>
#include <array>

struct Point {
    double x, y;
    Point operator-(const Point& b) const { return {x - b.x, y - b.y}; }
    Point operator+(const Point& b) const { return {x + b.x, y + b.y}; }
    Point operator*(double s) const { return {x * s, y * s}; }
};

double dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }
double norm(const Point& a) { return std::sqrt(dot(a, a)); }
Point normalize(const Point& a) { double n = norm(a); return {a.x / n, a.y / n}; }

// Compute the four rectangle corners of a capsule
std::array<Point, 4> capsule_corners(const Point& p1, const Point& p2, double width) {
    Point dir = normalize(p2 - p1);
    Point normal = {-dir.y, dir.x};
    double hw = width / 2.0;
    return {p1 + normal * hw, p1 - normal * hw, p2 - normal * hw, p2 + normal * hw};
}

// Check if point p is inside the capsule defined by (a1, a2, width)
bool point_in_capsule(const Point& p, const Point& a1, const Point& a2, double width) {
    Point ab = a2 - a1;
    double len2 = dot(ab, ab);
    double t = len2 > 0 ? dot(p - a1, ab) / len2 : 0;
    t = std::max(0.0, std::min(1.0, t));
    Point proj = a1 + ab * t;
    return norm(p - proj) <= width / 2.0;
}

// Main coverage test
bool is_covered(const Point& a1, const Point& a2, double wa,
                const Point& b1, const Point& b2, double wb) {
