**Java代码示例：**

```java
import java.util.*;

public class StaircaseWays {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("请输入台阶数n：");
        int n = scanner.nextInt();
        scanner.close();

        List<List<Integer>> result = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        dfs(n, path, result);

        System.out.println("总共有 " + result.size() + " 种走法：");
        for (List<Integer> way : result) {
            System.out.println(way);
        }
    }

    // 回溯递归
    private static void dfs(int n, List<Integer> path, List<List<Integer>> result) {
        if (n == 0) {
            result.add(new ArrayList<>(path));
            return;
        }
        if (n >= 1) {
            path.add(1);
            dfs(n - 1, path, result);
            path.remove(path.size() - 1);
        }
        if (n >= 2) {
            path.add(2);
            dfs(n - 2, path, result);
            path.remove(path.size() - 1);
        }
    }
}
```

