**Sample Java code:**

```java
import java.util.*;

public class StaircaseWays {
    public static void main(String[] args) {
        int n = 4; // You can change n to test other values
        List<List<Integer>> result = new ArrayList<>();
        backtrack(n, new ArrayList<>(), result);
        System.out.println("总共有 " + result.size() + " 种走法：");
        for (List<Integer> way : result) {
            System.out.println(way);
        }
    }

    private static void backtrack(int n, List<Integer> path, List<List<Integer>> result) {
        int sum = 0;
        for (int step : path) sum += step;
        if (sum == n) {
            result.add(new ArrayList<>(path));
            return;
        }
        if (sum > n) return;
        // Try 1 step
        path.add(1);
        backtrack(n, path, result);
        path.remove(path.size() - 1);
        // Try 2 steps
        path.add(2);
        backtrack(n, path, result);
        path.remove(path.size() - 1);
    }
}
