        int R = x[0] + (x[1] - x[0]);
        for (int i = 1; i < n; ++i) {
            int d;
            if (i == n - 1) d = x[i] - x[i-1];
            else d = min(x[i] - x[i-1], x[i+1] - x[i]);
            int low = x[i] - d, high = x[i] + d;
            L = max(L, low);
            R = min(R, high);
        }
        unordered_set<int> s(x.begin(), x.end());
        bool found = false;
        for (int p = L; p <= R; ++p) {
            if (s.count(p) == 0) {
